<script lang="ts">
 import{onMount}from'svelte';
 import type{DesignSnapshot,DesignOperation,DesignElement}from'@schubert/contracts';
 import{targetMeasure,parseMillimetres,applyOperations}from'@schubert/geometry';
 import MeasurementField from'./MeasurementField.svelte';
 import{describeStudioIssue}from'./issues.ts';
 let{snapshot,selectedId='',disabled=false,rules=[],onapply,onclose}:{snapshot:DesignSnapshot;selectedId?:string;disabled?:boolean;rules?:any[];onapply:(ops:DesignOperation[])=>void;onclose:()=>void}=$props();
 type Kind=DesignSnapshot['constraints'][number]['kind'];type Ref={elementId:string;feature:string};
 const names:Record<Kind,string>={coincident:'Deckungsgleiche Punkte',horizontal:'Waagerecht im Grundriss',vertical:'Senkrecht im Grundriss',parallel:'Parallele Wandachsen',perpendicular:'Rechtwinklige Wandachsen',distance:'Punktabstand',centered:'Zentrierung',fixed:'Gesperrter fester Bezug',minimum_clearance:'Mindestabstand'};
 const featureNames:Record<string,string>={point:'Bezugspunkt',origin:'Lokaler Ursprung',start:'Wandanfang',end:'Wandende',center:'Mittelpunkt',axis:'Wandachse',footprint:'Grundrisskörper',boundary:'Begrenzung / Innenabstand'};
 let dialog:HTMLDialogElement,kind=$state<Kind>('distance'),refs:Ref[]=$state([{elementId:'',feature:'point'},{elementId:'',feature:'point'}]),value=$state(''),ruleId=$state(''),error=$state(''),threePoints=$state(false),editingId=$state('');
 const available=$derived(snapshot.elements.filter(e=>kind==='fixed'||['parallel','perpendicular'].includes(kind)?kind==='fixed'||e.kind==='wall':kind==='minimum_clearance'?['node','wall','stone_piece','catalog_object','surface','room','clearance','grave_border'].includes(e.kind):['node','wall','stone_piece','catalog_object','surface','technical_note','grave_border'].includes(e.kind)));
 const needsMeasure=$derived(kind==='distance'||kind==='minimum_clearance');
 onMount(()=>{reset();dialog.showModal();return()=>dialog.close();});
 function features(element:DesignElement|undefined):Array<[string,string]>{if(!element)return[];if(kind==='fixed')return[['origin','Gesperrtes Element']];if(['parallel','perpendicular'].includes(kind))return[['axis','Wandachse']];if(element.kind==='node'||element.kind==='technical_note')return[['point','Bezugspunkt']];if(kind==='minimum_clearance')return element.kind==='wall'?[['footprint','Wandkörper im Grundriss'],['axis','Wandachse'],['boundary','Wandkontur']]:[['footprint','Gefüllte Grundrisskontur'],['boundary','Begrenzung / Innenabstand']];if(element.kind==='wall')return[['start','Wandanfang'],['end','Wandende'],['center','Wandmitte']];return[['center','Mittelpunkt der Maßhülle'],['origin','Lokaler Ursprung']];}
 function reset(){const count=kind==='fixed'?1:kind==='centered'&&threePoints?3:2;refs=Array.from({length:count},(_,i)=>{const id=i===0&&available.some(e=>e.id===selectedId)?selectedId:'',element=snapshot.elements.find(e=>e.id===id);return{elementId:id,feature:features(element)[0]?.[0]??'point'};});error='';}
 function choose(index:number){const element=snapshot.elements.find(e=>e.id===refs[index].elementId);refs[index].feature=features(element)[0]?.[0]??'point';}
 function edit(id:string){const c=snapshot.constraints.find(c=>c.id===id);if(!c)return;editingId=id;kind=c.kind;threePoints=c.kind==='centered'&&c.refs.length===3;refs=structuredClone($state.snapshot(c.refs));value=c.measureId?snapshot.measurements[c.measureId]?.valueMm??'':'';ruleId=c.ruleVersionId??'';error='';dialog.querySelector('form')?.scrollIntoView({block:'start',behavior:'smooth'});}
 function cancelEdit(){editingId='';value='';ruleId='';reset();}
 function add(event:SubmitEvent){event.preventDefault();error='';try{if(refs.some(r=>!r.elementId))throw Error('Alle konkreten Bezugselemente auswählen.');const previous=snapshot.constraints.find(c=>c.id===editingId),measureId=needsMeasure?previous?.measureId??crypto.randomUUID():null,parsed=value.trim()?parseMillimetres(value):null;if(needsMeasure&&value.trim()&&(parsed===null||Number(parsed)<0))throw Error('Einen eindeutigen nichtnegativen Abstand in mm eingeben.');const ops:DesignOperation[]=[];if(previous)ops.push({type:'remove_constraint',constraintId:previous.id});const existing=measureId?snapshot.measurements[measureId]:null;if(existing&&parsed!==existing.valueMm)ops.push({type:'set_design_target',measureId:measureId!,valueMm:parsed});ops.push({type:'add_constraint',constraint:{id:previous?.id??crypto.randomUUID(),kind,refs:refs.map(r=>({elementId:r.elementId,feature:r.feature})),measureId,ruleVersionId:ruleId||null},...(measureId&&!existing?{measurements:{[measureId]:targetMeasure(parsed)}}:{})});applyOperations(snapshot,ops);onapply(ops);cancelEdit();}catch(problem){error=(problem as Error).message;}}
 function remove(id:string){error='';try{onapply([{type:'remove_constraint',constraintId:id}]);}catch(problem){error=(problem as Error).message;}}
</script>
<dialog bind:this={dialog} oncancel={onclose} aria-labelledby="binding-title"><header><span>BEZÜGE · ABSTÄNDE · LAGE</span><h2 id="binding-title">Geometrie verbindlich prüfen.</h2><p>Bindungen sichern die eingestellte Geometrie. Widersprüche werden vor dem Speichern angezeigt. Maße bleiben von Aufmaß und fachlicher Freigabe getrennt.</p></header><div class="content">
 {#if error}<p class="alert" role="alert">{describeStudioIssue(snapshot,error).message.replace(/Bindung [a-f0-9-]{36}:/gi,'Diese Bindung:')}</p>{/if}
 <form onsubmit={add}><fieldset disabled={disabled}><label>Bindung<select bind:value={kind} onchange={reset}>{#each Object.entries(names) as [key,name]}<option value={key}>{name}</option>{/each}</select></label>{#if kind==='centered'}<label class="check"><input type="checkbox" bind:checked={threePoints} onchange={reset}/> Ersten Punkt mittig zwischen zwei Begrenzungspunkten festlegen</label>{/if}
 {#each refs as ref,index}<div class="reference"><label>{kind==='centered'&&threePoints&&index===0?'Zu zentrierender Bezug':`Bezug ${index+1}`}<select bind:value={ref.elementId} onchange={()=>choose(index)} required><option value="">Element auswählen</option>{#each available as element}<option value={element.id}>{element.label}</option>{/each}</select></label><label>Geometrischer Bezug<select bind:value={ref.feature} required>{#each features(snapshot.elements.find(e=>e.id===ref.elementId)) as [key,name]}<option value={key}>{name}</option>{/each}</select></label></div>{/each}
 {#if needsMeasure}<label>{kind==='minimum_clearance'?'Mindestens freier Abstand':'Exakter Punktabstand'} (mm)<input bind:value={value} inputmode="decimal" placeholder="Unbekannt"/></label><p class="hint">Punktabstände berücksichtigen X, Y und Z. Konturabstände beziehen sich auf den Grundriss; Kreislinien werden analytisch geprüft. „Begrenzung“ erlaubt den Innenabstand innerhalb einer Raum- oder Bauteilkontur.</p>{/if}
 {#if kind==='fixed'}<p class="hint">Das Element oder seine Gruppe zuerst sperren. Die Bindung überprüft den festen Bezug zusätzlich.</p>{/if}<label>Geprüfter Regelstand (optional)<select bind:value={ruleId}><option value="">Eigene geometrische Bindung</option>{#each rules as rule}<option value={rule.id}>{rule.name}</option>{/each}</select></label><div class="edit-actions"><button class="btn primary" type="submit">{editingId?'Änderung der Bindung übernehmen':'Bindung zum Plan hinzufügen'}</button>{#if editingId}<button class="btn" type="button" onclick={cancelEdit}>Bearbeitung abbrechen</button>{/if}</div><p class="hint">Bei einer Änderung bleiben andere Bauteile an ihrer Position. Eine widersprüchliche Bindung wird mit ihren betroffenen Bezügen angezeigt; sie verschiebt keine fremden Elemente unbemerkt.</p></fieldset></form>
 <section><h3>Gespeicherte Bindungen</h3>{#each snapshot.constraints as constraint}<article data-constraint-id={constraint.id} class:editing={editingId===constraint.id}><div><strong>{names[constraint.kind]}</strong><p>{constraint.refs.map(r=>{const e=snapshot.elements.find(e=>e.id===r.elementId);return`${e?.label??'Fehlender Bezug'} · ${featureNames[r.feature]??'Geometrischer Bezug'}`;}).join(' / ')}</p>{#if constraint.ruleVersionId}<p>Regel: {rules.find(r=>r.id===constraint.ruleVersionId)?.name??'Versionierter Regelbezug'}</p>{/if}{#if constraint.measureId}<MeasurementField {snapshot} measureId={constraint.measureId} label="Gebundener Abstand" onchange={ops=>{try{onapply(ops);}catch(problem){error=(problem as Error).message;}}} {disabled}/>{/if}</div><div class="row-actions"><button class="text" type="button" onclick={()=>edit(constraint.id)} disabled={disabled}>Bearbeiten</button><button class="text" type="button" onclick={()=>remove(constraint.id)} disabled={disabled}>Entfernen</button></div></article>{:else}<p class="hint">Noch keine zusätzlichen Bindungen. Gesperrter Bestand, gemeinsame Wandknoten und Produktnennmaße behalten ihre eigenen Schutzregeln.</p>{/each}</section>
 </div><footer><button class="btn" onclick={onclose}>Zurück zum Plan</button></footer></dialog>
<style>
dialog{width:min(690px,94vw);max-height:92dvh;padding:0;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink)}dialog::backdrop{background:#15231fcc;backdrop-filter:blur(3px)}header{padding:25px 30px;background:var(--paper);border-bottom:1px solid var(--line)}header>span{font-size:9px;letter-spacing:.12em;color:var(--muted)}h2{font-size:26px;font-weight:500;letter-spacing:-.8px;margin:12px 0}p{font-size:11px;line-height:1.8;color:var(--muted)}.content{padding:25px 30px;max-height:64dvh;overflow:auto}fieldset{padding:0;margin:0;border:0}label{display:block;font-size:12px;line-height:1.6;color:var(--muted);margin:0 0 16px}input,select{box-sizing:border-box;width:100%;min-height:42px;padding:10px;margin-top:6px;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink);font:inherit;font-size:13px}.reference{display:grid;grid-template-columns:1.2fr 1fr;gap:12px}.check{display:flex;gap:10px}.check input{width:15px;min-height:15px;margin-top:3px;accent-color:var(--forest)}.btn{font-size:11px;min-height:42px}.btn.primary{color:var(--on-accent,#fff);background:var(--forest)}section{padding-top:25px;margin-top:25px;border-top:1px solid var(--line)}h3{font-size:14px;font-weight:500}article{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:14px 0;border-bottom:1px solid var(--line)}article strong{font-size:12px;font-weight:500}article p{margin:5px 0 0}.text{color:var(--forest);background:none;border:0;font-size:11px;min-height:40px;cursor:pointer}.alert{background:var(--wash);color:var(--muted);padding:12px;border:1px solid var(--line);white-space:pre-wrap}footer{display:flex;justify-content:flex-end;padding:18px 30px;border-top:1px solid var(--line)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--forest);outline-offset:3px}@media(max-width:600px){header,.content{padding:22px}.reference{grid-template-columns:1fr;gap:0}input,select{font-size:16px}}
label{font-size:13px}p,.btn,.text{font-size:12px}article>div{flex:1;min-width:0}.edit-actions,.row-actions{display:flex;flex-wrap:wrap;gap:8px}article>.row-actions{flex:0 0 auto;flex-direction:column}.editing{background:var(--wash)}@media(max-width:600px){.btn,.text{min-height:48px}}
</style>
